from django.utils.text import slugify


def populate_problem_data(apps, schema_editor):
    Problem = apps.get_model('revise', 'Problem')
    Pattern = apps.get_model('revise', 'Pattern')
    UserProblem = apps.get_model('revise', 'UserProblem')
    DSASheet = apps.get_model('revise', 'DSASheet')

    for problem in Problem.objects.order_by('id'):
        base_slug = slugify(problem.title) or f'problem-{problem.leetcode_id}'
        slug = base_slug
        suffix = 1
        while Problem.objects.filter(slug=slug).exclude(pk=problem.pk).exists():
            slug = f'{base_slug}-{suffix}'
            suffix += 1
        problem.slug = slug
        problem.save(update_fields=['slug'])

        if getattr(problem, 'pattern_id', None):
            problem.patterns.add(problem.pattern)

    for user_problem in UserProblem.objects.all():
        if user_problem.last_reviewed and user_problem.next_revision:
            user_problem.interval = max(0, (user_problem.next_revision - user_problem.last_reviewed).days)
            user_problem.save(update_fields=['interval'])

    for sheet_name in ['Blind 75', 'NeetCode 150']:
        DSASheet.objects.get_or_create(name=sheet_name)


